import java.util.*;
import java.util.concurrent.*;

class Solution {
  public List<String> crawl(String startUrl, HtmlParser htmlParser) {
    String host = hostOf(startUrl);
    Set<String> seen = ConcurrentHashMap.newKeySet();
    seen.add(startUrl);
    ExecutorService pool = Executors.newFixedThreadPool(8);
    try {
      List<Future<List<String>>> pending = new ArrayList<>();
      pending.add(pool.submit(() -> htmlParser.getUrls(startUrl)));
      // fetch level by level; each level's pages are fetched in parallel
      while (!pending.isEmpty()) {
        List<Future<List<String>>> next = new ArrayList<>();
        for (Future<List<String>> f : pending) {
          for (String url : f.get()) {
            if (hostOf(url).equals(host) && seen.add(url)) next.add(pool.submit(() -> htmlParser.getUrls(url)));
          }
        }
        pending = next;
      }
    } catch (InterruptedException | ExecutionException e) {
      throw new RuntimeException(e);
    } finally {
      pool.shutdown();
    }
    return new ArrayList<>(seen);
  }

  private String hostOf(String url) {
    int start = url.indexOf("//") + 2, end = url.indexOf('/', start);
    return end < 0 ? url.substring(start) : url.substring(start, end);
  }
}
